<script setup>
import { reactive,ref,onMounted,onBeforeUnmount,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { notify,confirmDialog } from '../../services/notifications.js';
import { useCollection,money } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';
const route=useRoute(),router=useRouter(),tab=ref(String(route.query.tab||'general')),loading=ref(true),saving=ref(false),error=ref(''),busyWa=ref(false);
const settings=reactive({trialDays:15,magicLinkMinutes:15,contact:{email:'',phone:'',whatsapp:''},home:{eyebrow:'',title:'',subtitle:'',ctaText:'',heroImage:'',benefits:[],testimonials:[],faq:[]}});
const wa=reactive({status:'disconnected',qr:null,error:'',clientId:''});let polling;
const tabs=[['general','General','settings'],['planes','Planes','crown'],['contacto','Contacto','phone'],['whatsapp','WhatsApp','whatsapp'],['home','Página de inicio','home']];
const {rows,loading:plansLoading,error:plansError,meta,load:loadPlans,updateQuery}=useCollection('/admin/plans');
const planColumns=[{key:'name',label:'Plan'},{key:'price',label:'Precio'},{key:'maxStores',label:'Tiendas'},{key:'maxProducts',label:'Productos'},{key:'active',label:'Estado'}];
watch(tab,value=>{router.replace({query:{tab:value}});if(value==='whatsapp'){poll();polling=setInterval(poll,3000)}else{clearInterval(polling);polling=null}});
onMounted(async()=>{try{const data=await api.get('/admin/settings');Object.assign(settings,data);settings.contact={email:'',phone:'',whatsapp:'',...data.contact};settings.home={eyebrow:'',title:'',subtitle:'',ctaText:'',heroImage:'',benefits:[],testimonials:[],faq:[],...data.home};if(tab.value==='whatsapp'){poll();polling=setInterval(poll,3000)}}catch(e){error.value=e.message}finally{loading.value=false}});
onBeforeUnmount(()=>clearInterval(polling));
async function save(){saving.value=true;error.value='';try{await api.put('/admin/settings',settings);notify.success('Configuración guardada.')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
async function removePlan(row){if(!await confirmDialog({title:'Desactivar plan',message:`El plan ${row.name} dejará de ofrecerse a nuevos vendedores. Revisá las asignaciones existentes antes de hacer cambios en sus límites.`,confirmText:'Desactivar',danger:true}))return;try{await api.delete(`/admin/plans/${row._id}`);notify.success('Plan desactivado.');loadPlans()}catch(e){notify.error(e.message)}}
async function poll(){try{Object.assign(wa,await api.get('/admin/whatsapp/status'))}catch(e){wa.error=e.message}}
async function connect(){busyWa.value=true;try{Object.assign(wa,await api.post('/admin/whatsapp/connect'));await poll();notify.info('Preparando WhatsApp. El QR aparecerá cuando esté disponible.')}catch(e){notify.error(e.message)}finally{busyWa.value=false}}
async function disconnect(){if(!await confirmDialog({title:'Desconectar WhatsApp',message:'Para volver a vincular la cuenta podría ser necesario escanear un nuevo QR.',confirmText:'Desconectar'}))return;busyWa.value=true;try{await api.post('/admin/whatsapp/disconnect');await poll();notify.success('WhatsApp desconectado.')}catch(e){notify.error(e.message)}finally{busyWa.value=false}}
const waLabels={disconnected:'Desconectado',connecting:'Preparando conexión',initializing:'Inicializando',qr:'Esperando escaneo',authenticated:'Autenticado',ready:'Conectado',connected:'Conectado',error:'Error de conexión',disabled:'Deshabilitado'};
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">A TU MEDIDA</p><h1>Configuración</h1><p>Definí cómo funciona y cómo se presenta mi tienda ya.</p></div><a href="/" target="_blank" rel="noopener" class="btn btn-secondary"><Icon name="external" :size="15"/>Ver página de inicio</a></header><nav class="p-tabs" aria-label="Secciones de configuración"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]"><Icon :name="t[2]" :size="16"/>{{t[1]}}</button></nav><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><template v-else>
 <section v-if="tab==='planes'"><div class="p-section-title"><div><h2>Planes comerciales</h2><p>Diseñá opciones para cada etapa del emprendimiento.</p></div><RouterLink to="/app/settings/plans/new" class="btn btn-primary"><Icon name="plus" :size="15"/>Crear plan</RouterLink></div><div v-if="plansError" class="p-error">{{plansError}}</div><DataTable :rows="rows" :columns="planColumns" :loading="plansLoading" server :total="meta.total" :page="meta.page" :limit="meta.limit" @query-change="updateQuery"><template #cell-name="{row}"><div class="p-product-cell"><span class="p-product-thumb"><Icon :name="row.icon"/></span><span><strong>{{row.name}}</strong><small>{{row.durationDays}} días <span v-if="row.featured">· Recomendado</span></small></span></div></template><template #cell-price="{row}"><strong>{{money(row.price)}}</strong><small v-if="row.previousPrice>row.price"><del>{{money(row.previousPrice)}}</del></small></template><template #cell-maxProducts="{value}">{{value===0?'Ilimitados':value}}</template><template #cell-active="{value}"><span class="p-badge" :class="value?'green':'red'">{{value?'Disponible':'Desactivado'}}</span></template><template #actions="{row}"><RouterLink :to="`/app/settings/plans/${row._id}`" class="p-icon-btn" title="Editar plan"><Icon name="edit" :size="14"/></RouterLink><button v-if="row.active" class="p-icon-btn danger" title="Desactivar plan" @click="removePlan(row)"><Icon name="trash" :size="14"/></button></template></DataTable></section>
 <section v-else-if="tab==='whatsapp'" class="p-section-card"><div class="p-section-title"><div><h2>WhatsApp de la plataforma</h2><p>Vinculá una cuenta desde WhatsApp → Dispositivos vinculados.</p></div><span class="p-badge" :class="['ready','connected'].includes(wa.status)?'green':'orange'">{{waLabels[wa.status]||wa.status}}</span></div><div class="p-two-column"><div><div class="p-info"><strong>Cómo vincular</strong><br/>1. Presioná Conectar y esperá a que aparezca el QR.<br/>2. Abrí WhatsApp en tu teléfono y entrá a Dispositivos vinculados.<br/>3. Elegí Vincular un dispositivo y escaneá el código.<br/>La conexión se verifica automáticamente cada 3 segundos.</div><p class="p-help">Instancia: <strong>{{wa.clientId||'Configurada en el servidor'}}</strong>. La sesión se conserva entre reinicios.</p><div v-if="wa.error" class="p-error">{{wa.error}}</div><div class="p-inline"><button class="btn btn-primary" :disabled="busyWa||['ready','connected','connecting','initializing','qr'].includes(wa.status)" @click="connect"><Icon name="whatsapp" :size="17"/>{{busyWa?'Procesando...':'Conectar WhatsApp'}}</button><button class="btn btn-secondary" :disabled="busyWa||wa.status==='disconnected'" @click="disconnect">Desconectar</button><button class="p-icon-btn" title="Actualizar estado" @click="poll"><Icon name="refresh" :size="16"/></button></div></div><div style="text-align:center"><img v-if="wa.qr" :src="wa.qr" class="p-qr" alt="Código QR para vincular WhatsApp"/><div v-else class="p-whatsapp-preview"><div><Icon name="whatsapp" :size="48"/><p>{{['ready','connected'].includes(wa.status)?'Tu cuenta está conectada.':'El código QR aparecerá acá.'}}</p><span v-if="['connecting','initializing'].includes(wa.status)" class="p-spinner"/></div></div></div></div></section>
 <form v-else @submit.prevent="save" class="p-form">
  <section v-if="tab==='general'" class="p-section-card"><div class="p-section-title"><div><h2>Acceso y período de prueba</h2><p>Estas reglas se aplican a nuevos accesos y nuevas pruebas.</p></div><Icon name="shield"/></div><div class="p-form-grid"><div class="p-field"><label for="trial-days">Días de prueba inicial</label><input id="trial-days" v-model.number="settings.trialDays" type="number" min="0" max="365" required/><small>0 deshabilita las pruebas nuevas. No modifica las pruebas que ya comenzaron.</small></div><div class="p-field"><label for="magic-minutes">Vigencia del enlace de ingreso (minutos)</label><input id="magic-minutes" v-model.number="settings.magicLinkMinutes" type="number" min="1" max="1440" required/><small>Cada enlace puede usarse una sola vez. Los vendedores pueden solicitar uno nuevo.</small></div></div></section>
  <section v-else-if="tab==='contacto'" class="p-section-card"><div class="p-section-title"><div><h2>Contacto con mi tienda ya</h2><p>Se muestra en la página de inicio y en la sección Tu plan.</p></div><Icon name="phone"/></div><div class="p-form-grid"><div class="p-field"><label for="platform-email">Correo de contacto</label><input id="platform-email" v-model.trim="settings.contact.email" type="email" placeholder="hola@tu-dominio.com"/></div><div class="p-field"><label for="platform-phone">Teléfono visible</label><input id="platform-phone" v-model.trim="settings.contact.phone" type="tel" placeholder="+54 11 1234 5678"/></div><div class="p-field"><label for="platform-wa">WhatsApp de soporte y planes</label><input id="platform-wa" v-model.trim="settings.contact.whatsapp" type="tel" placeholder="5491112345678"/><small>Incluí código de país y área. Se utiliza para abrir una conversación.</small></div></div></section>
  <template v-else-if="tab==='home'"><section class="p-section-card"><div class="p-section-title"><div><h2>Portada de la plataforma</h2><p>Una primera impresión que invite a emprender.</p></div><Icon name="home"/></div><div class="p-form-grid"><div class="p-field full"><label for="home-eyebrow">Texto destacado sobre el título</label><input id="home-eyebrow" v-model="settings.home.eyebrow" maxlength="100"/></div><div class="p-field full"><label for="home-title">Título principal</label><input id="home-title" v-model="settings.home.title" required maxlength="180"/></div><div class="p-field full"><label for="home-subtitle">Descripción principal</label><textarea id="home-subtitle" v-model="settings.home.subtitle" maxlength="1000" rows="3"/></div><div class="p-field"><label for="home-cta">Texto del botón para empezar</label><input id="home-cta" v-model="settings.home.ctaText" maxlength="60"/></div><div class="p-field"><label for="home-hero">Imagen de portada (URL HTTPS)</label><input id="home-hero" v-model.trim="settings.home.heroImage" type="url" placeholder="https://..."/><small>Opcional. Elegí una imagen sobre la que tengas derechos de uso.</small></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Beneficios de la plataforma</h2><p>Mostrá qué hace más simple el día a día.</p></div></div><div v-for="(b,i) in settings.home.benefits" :key="i" class="p-nested-card"><header><strong>Beneficio {{i+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar beneficio" @click="settings.home.benefits.splice(i,1)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field"><label :for="`benefit-title-${i}`">Título</label><input :id="`benefit-title-${i}`" v-model="b.title" required maxlength="100"/></div><div class="p-field"><label :for="`benefit-icon-${i}`">Ícono</label><select :id="`benefit-icon-${i}`" v-model="b.icon"><option v-for="icon in ['store','palette','credit','credit-card','package','chart','phone','shield','truck','sparkles']" :key="icon">{{icon}}</option></select></div><div class="p-field full"><label :for="`benefit-desc-${i}`">Descripción</label><textarea :id="`benefit-desc-${i}`" v-model="b.description" rows="2" maxlength="600"/></div></div></div><button type="button" class="p-add-dashed" :disabled="settings.home.benefits.length>=12" @click="settings.home.benefits.push({title:'',description:'',icon:'sparkles'})"><Icon name="plus" :size="15"/>Agregar beneficio</button></section><section class="p-section-card"><div class="p-section-title"><div><h2>Experiencias de vendedores</h2><p>Publicá testimonios reales con autorización de sus autores.</p></div></div><div v-for="(t,i) in settings.home.testimonials" :key="i" class="p-nested-card"><header><strong>Experiencia {{i+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar experiencia" @click="settings.home.testimonials.splice(i,1)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field"><label :for="`test-name-${i}`">Nombre</label><input :id="`test-name-${i}`" v-model="t.name" required maxlength="100"/></div><div class="p-field"><label :for="`test-business-${i}`">Emprendimiento</label><input :id="`test-business-${i}`" v-model="t.business" maxlength="120"/></div><div class="p-field full"><label :for="`test-quote-${i}`">Testimonio</label><textarea :id="`test-quote-${i}`" v-model="t.quote" required rows="3" maxlength="1500"/></div></div></div><button type="button" class="p-add-dashed" :disabled="settings.home.testimonials.length>=20" @click="settings.home.testimonials.push({name:'',business:'',quote:''})"><Icon name="plus" :size="15"/>Agregar experiencia</button></section><section class="p-section-card"><div class="p-section-title"><h2>Preguntas frecuentes</h2></div><div v-for="(f,i) in settings.home.faq" :key="i" class="p-nested-card"><header><strong>Pregunta {{i+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar pregunta" @click="settings.home.faq.splice(i,1)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field full"><label :for="`faq-question-${i}`">Pregunta</label><input :id="`faq-question-${i}`" v-model="f.question" required maxlength="300"/></div><div class="p-field full"><label :for="`faq-answer-${i}`">Respuesta</label><textarea :id="`faq-answer-${i}`" v-model="f.answer" required maxlength="2000" rows="3"/></div></div></div><button type="button" class="p-add-dashed" :disabled="settings.home.faq.length>=30" @click="settings.home.faq.push({question:'',answer:''})"><Icon name="plus" :size="15"/>Agregar pregunta</button></section></template><footer class="p-form-footer"><small>Guardá para aplicar los cambios de configuración.</small><div class="p-form-actions"><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':'Guardar configuración'}}</button></div></footer>
 </form></template></div></template>
